    addBehavior = 'reject';
    fireEvent.click(screen.getByText('添加新文件夹'));
    await waitFor(() =>
      expect(screen.getByText(/添加 workspace 失败：.*canonicalize: 入库失败/) !== null).toBe(true),
    );
